WebLink.url:
if('{!Cloudrop__Cloud_Storage__c.RecordType}' == 'Folder'){
alert('Custom view is not available for folders');
}
else{
var furl =document.domain;
var ffurl = furl.split('\.');
var clouddrop_RelateTo = "{!Cloudrop__Cloud_Storage__c.Cloudrop__Relate_To__c}";
var clouddrop_ObjectId="{!Cloudrop__Cloud_Storage__c.Cloudrop__ObjectId__c}";
var staticURL = "https://cloudrop."+ffurl[0]+".visual.force.com/apex/Viewfilepage_Dynamic?FileId={!Cloudrop__Cloud_Storage__c.Id}&RecId=";
if(clouddrop_ObjectId=='')
{
staticURL = staticURL+clouddrop_RelateTo;
}
else
{
staticURL = staticURL+clouddrop_ObjectId;
}
location.replace(staticURL);
}
